import logging
import time
from telnetlib import Telnet

from taf.hw.optical_switch.exceptions import OpticalSwitchConnectionError, Timeout


class TelnetClient:

    def __init__(self, host, port, timeout, encoding):
        self._encoding = encoding
        self._host = host
        self._port = port
        self._timeout = timeout
        self._logger = logging.getLogger(__name__)
        self._logger.setLevel(logging.DEBUG)
        try:
            self._logger.debug(
                f"Connecting to optical switch under {self._host}:{self._port}"
            )
            self.telnet_con = Telnet(self._host, self._port, self._timeout)
        except IOError as e:
            self._logger.error(str(e))
            raise OpticalSwitchConnectionError(
                f"Cannot connect to optical switch host={self._host}:{self._port}"
            )

    def write_cmd(self, telnet_msg):
        try:
            self._logger.debug(f"Writing telnet message: {telnet_msg}")
            self.telnet_con.write(telnet_msg)
        except OSError as e:
            msg = "Telnet connection closed unexpectedly during writing."
            raise OpticalSwitchConnectionError(msg) from e

    def collect_output(self):
        start = time.time()
        while time.time() - start < self._timeout:
            try:
                response = self.telnet_con.read_very_eager()
                if response and not response.isspace():
                    self._logger.debug(f"Telnet response: {response}")
                    return response.decode(self._encoding)
            except EOFError as e:
                msg = "Telnet connection closed unexpectedly during output collection."
                raise OpticalSwitchConnectionError(msg) from e
        raise Timeout("Telnet connection timed out.")

    def collect_output_until(self, match, timeout=2):
        try:
            response = self.telnet_con.read_until(match, timeout)
            self._logger.debug(f"Telnet response: {response}")
        except EOFError as e:
            msg = "Telnet connection closed unexpectedly during output collection."
            raise OpticalSwitchConnectionError(msg) from e
        return response.decode(self._encoding)

    def close(self):
        self.telnet_con.close()
